INSERT OR IGNORE INTO settings (key, value) VALUES ('hotkey_config', '{"bindings":[{"action":"toggle_window","keys":["CommandOrControl+Shift+D"],"enabled":true,"scope":"global","category":"Global","description":"Toggle window"},{"action":"select_next","keys":["j","ArrowDown"],"enabled":true,"scope":"app","category":"Navigation","description":"Next notification"},{"action":"select_prev","keys":["k","ArrowUp"],"enabled":true,"scope":"app","category":"Navigation","description":"Previous notification"},{"action":"focus_search","keys":["f"],"enabled":true,"scope":"app","category":"Navigation","description":"Focus search"},{"action":"clear_selection","keys":["Escape"],"enabled":true,"scope":"app","category":"Navigation","description":"Clear selection"},{"action":"mark_selected_read","keys":["Enter","r"],"enabled":true,"scope":"app","category":"Actions","description":"Mark read"},{"action":"delete_selected","keys":["d","Backspace"],"enabled":true,"scope":"app","category":"Actions","description":"Delete"},{"action":"focus_terminal","keys":["t"],"enabled":true,"scope":"app","category":"Actions","description":"Focus terminal"},{"action":"mark_all_read","keys":["R"],"enabled":true,"scope":"app","category":"Actions","description":"Mark all read"},{"action":"clear_all","keys":["D"],"enabled":true,"scope":"app","category":"Actions","description":"Clear all"},{"action":"filter_all","keys":["1"],"enabled":true,"scope":"app","category":"Filters","description":"All"},{"action":"filter_unread","keys":["2"],"enabled":true,"scope":"app","category":"Filters","description":"Unread"},{"action":"filter_read","keys":["3"],"enabled":true,"scope":"app","category":"Filters","description":"Read"},{"action":"toggle_help","keys":["?"],"enabled":true,"scope":"app","category":"Help","description":"Toggle help"}]}');
